const openWindow=(href,...args)=>window.open(localLink(href),...args);
const changeAddress=href=>history.replaceState(null,'',localLink(href));
document.addEventListener('click',event=>{if(!explicitDemo)return;const anchor=event.target.closest('a[href]');if(anchor){const href=anchor.getAttribute('href');anchor.setAttribute('href',localLink(href));}},true);

const route=resolveRoute(location.pathname,location.search,{view:document.documentElement.dataset.appView,page:document.documentElement.dataset.appPage});
let roleHomeApplied=false;
