 <header class="customer-header customer-container">${clientBrand()}<nav class="customer-nav" aria-label="Navegación del cliente"><a href="#food-menu" data-action="scroll-food">Nuestro menú</a><a href="#how-to-order" data-action="scroll-how">Cómo pedir</a>${lastToken?`<a href="/?view=track&token=${encodeURIComponent(lastToken)}">Seguir mi pedido</a>`:''}</nav><div class="customer-header-actions"><button class="theme-switch" aria-label="Cambiar tema" data-action="theme">${icon('sun')}</button><button class="customer-cart-top" data-action="customer-cart">${icon('bag')}<span>Mi pedido</span><b>${count}</b></button></div></header>
