function cartTotal(){return cart.reduce((a,x)=>a+(state.catalog.find(p=>p.id===x.productId)?.price||0)*x.qty,0);}
function customProduct(id){const p=state.catalog.find(p=>p.id===id);if(!p)return;if(!p.ingredients.length&&!p.options?.length){addCart(id,[]);return;}modal(esc(p.name),`<form id="custom-form"><div class="custom-product-summary">${foodPhoto(p)?`<img src="${esc(foodPhoto(p))}" alt="${esc(p.name)}">`:''}<div><span>HAZLO A TU MANERA</span><strong>${money(p.price)}</strong><small>${esc(p.description)}</small></div></div>${p.options?.length?`<div class="field"><label for="product-option">Elige tu opción</label><select id="product-option" name="productOption" required>${p.options.map(o=>`<option value="${esc(o.value||o.label||o)}">${esc(o.label||o.value||o)}</option>`).join('')}</select></div>`:''}<p class="form-note" style="margin:0 0 16px">Desmarca los ingredientes que no deseas.</p><div id="custom-modifiers">${p.ingredients.map((name,i)=>`<label class="check-line"><input type="checkbox" name="ingredient" value="${esc(name)}" checked><span>${esc(name)}</span></label>`).join('')}</div><div class="modal-actions"><button class="btn" type="button" data-action="close-modal">Cancelar</button><button class="btn primary" type="submit">Añadir · ${money(p.price)}</button></div></form>`);const choice=$('#product-option');if(choice){const refresh=()=>{const names=p.modifiersByOption?.[choice.value]?.length?p.modifiersByOption[choice.value]:(p.modifierNames||p.ingredients);$('#custom-modifiers').innerHTML=names.map(name=>`<label class="check-line"><input type="checkbox" name="ingredient" value="${esc(name)}" checked><span>${esc(name)}</span></label>`).join('');};choice.onchange=refresh;refresh();}$('#custom-form').onsubmit=e=>{e.preventDefault();const removed=$$('#custom-form input:not(:checked)').map(x=>x.value);addCart(id,removed,$('#custom-form select')?.value||'');closeModal();};}
function addCart(id,removed,option=''){if(readPendingOrder())return toast('Hay un pedido pendiente de recuperar. Usa el aviso del menú.',true);const key=id+':'+option+':'+removed.slice().sort().join('|');const found=cart.find(x=>x.key===key);if(found)found.qty=Math.min(20,found.qty+1);else cart.push({key,productId:id,qty:1,removed,option});saveClientCart();renderMenu();toast('Añadido a tu pedido.');}
function openCart(){const previous=$('#checkout-form');if(previous){checkoutDraft.rememberCustomer=previous.rememberCustomer?.checked===true;}if(previous)for(const name of ['customerName','phone','address','notes','deliveryType','table'])if(previous.elements[name])checkoutDraft[name]=previous.elements[name].value;const mesa=params.get('mesa');modal('Tu pedido',`<form id="checkout-form">${!preview&&!state.reception?.available?'<div class="offline-notice">El local no está recibiendo pedidos web ahora. Puedes conservar el carrito y consultar al personal.</div>':''}<div id="cart-lines">${cart.map((x,i)=>{const p=state.catalog.find(p=>p.id===x.productId);return p?`<div class="cart-row">${foodPhoto(p)?`<img class="cart-thumb" src="${esc(foodPhoto(p))}" alt="${esc(p.name)}">`:`<span class="item-emoji">${icon('bag')}</span>`}<div><strong>${esc(p.name)}${x.option?' · '+esc(x.option):''}</strong>${x.removed.length?`<small>Sin: ${esc(x.removed.join(', '))}</small>`:`<small>${money(p.price)}</small>`}</div><div class="quantity"><button type="button" data-action="cart-minus" data-index="${i}" aria-label="Quitar unidad">−</button><span>${x.qty}</span><button type="button" data-action="cart-plus" data-index="${i}" aria-label="Agregar unidad">+</button></div></div>`:'';}).join('')}</div><div class="total-box"><span>Total del pedido</span><strong>${money(cartTotal())}</strong></div><div class="form-grid"><div class="field"><label for="checkout-name">Nombre</label><input id="checkout-name" name="customerName" required maxlength="100" autocomplete="name"></div><div class="field"><label for="checkout-phone">Teléfono · opcional en el local</label><input id="checkout-phone" name="phone" type="tel" maxlength="20" autocomplete="tel"></div></div>${mesa?`<div class="banner-info">Estás ordenando desde la mesa ${esc(mesa)}.</div>`:`<div class="field"><label for="delivery-type">Entrega</label><select id="delivery-type" name="deliveryType"><option value="Retiro">Retiro en el local</option><option value="Mesa">En mi mesa</option><option value="Delivery">Delivery</option></select></div><div class="field" id="checkout-table-field" hidden><label for="checkout-table">Número de mesa</label><input id="checkout-table" name="table" type="number" min="1" max="999" step="1" placeholder="Número de tu mesa"></div><div class="field" id="delivery-address" hidden><label for="checkout-address">Dirección de entrega</label><textarea id="checkout-address" name="address" maxlength="300"></textarea></div>`}<div class="field"><label for="checkout-notes">Observaciones · opcional</label><textarea id="checkout-notes" name="notes" placeholder="Ej. sin servilletas" maxlength="400"></textarea></div><label class="check-line"><input id="checkout-remember" name="rememberCustomer" type="checkbox"><span>Quiero guardar mi nombre, teléfono e historial para mis próximas visitas. Opcional; requiere teléfono.</span></label><p class="form-note">Recibirás un número de turno y podrás seguir el pedido en esta página. Esta operación no realiza el cobro ni emite una factura.</p><div class="modal-actions"><button class="btn" type="button" data-action="close-modal">Seguir eligiendo</button><button class="btn primary" type="submit" ${!preview&&!state.reception?.available?'disabled':''}>${!navigator.onLine?'Carrito guardado · sin conexión':'Enviar pedido'} ${icon('right')}</button></div></form>`);const f=$('#checkout-form');for(const [name,value] of Object.entries(checkoutDraft))if(f.elements[name]&&name!=='rememberCustomer')f.elements[name].value=value;f.rememberCustomer.checked=checkoutDraft.rememberCustomer===true;const updateRequired=()=>{const type=f.deliveryType?.value;f.phone.required=f.rememberCustomer.checked||type==='Delivery';if($('#delivery-address')){$('#delivery-address').hidden=type!=='Delivery';f.address.required=type==='Delivery';}if($('#checkout-table-field')){$('#checkout-table-field').hidden=type!=='Mesa';f.table.required=type==='Mesa';}};f.rememberCustomer.onchange=updateRequired;if(f.deliveryType)f.deliveryType.onchange=updateRequired;updateRequired();f.onsubmit=e=>{e.preventDefault();submit(f,async()=>{if(!cart.length)throw new Error('Agrega productos al pedido.');const r=await submitCustomerOrder({name:f.customerName.value,phone:f.phone.value,rememberCustomer:f.rememberCustomer.checked,table:mesa||(f.deliveryType.value==='Mesa'?f.table.value:'Retiro'),deliveryType:mesa?'Mesa':f.deliveryType.value,address:f.address?.value||'',notes:f.notes.value,items:cart.map(({productId,qty,removed,option})=>({productId,qty,removed,option}))});localStorage.setItem(LAST_TOKEN_KEY,r.token);cart=[];saveClientCart();checkoutDraft={};closeModal();location.href=`/seguimiento.html?token=${encodeURIComponent(r.token)}`;});};}
let trackerPrevious='';
function renderTracker(){const token=params.get('token');const o=state.orders.find(o=>o.token===token);if(!o){$('#app').innerHTML=`<main class="tracker"><header class="public-header">${clientBrand()}</header>${empty('Pedido no encontrado','Revisa el enlace de seguimiento o consulta al personal.','bag')}<a class="btn full-width" href="/?view=menu">Volver al menú</a><p class="form-note">Comprueba que el enlace de seguimiento esté completo y consulta al encargado si el pedido no aparece.</p></main>`;return;}if(trackerPrevious&&trackerPrevious!==o.status&&o.status==='ready'){beep();notifyOrderReady(o);}trackerPrevious=o.status;const steps=['pending','preparing','ready','delivered'];const index=steps.indexOf(o.status);$('#app').innerHTML=`<main class="tracker"><header class="public-header">${clientBrand()}<span class="public-badge">Tu pedido</span></header><div class="demo-notice"><span class="tag">${preview?'VISTA PREVIA':'TU PEDIDO'}</span><span>${preview?'Seguimiento de prueba.':'Tu pedido se actualiza en tiempo real.'}</span></div><section class="tracker-head"><p>Tu número de turno es</p><div class="order-hero">#${o.number}</div><h2>${o.status==='pending'?'Enviado · pendiente de confirmación del local':orderLabels[o.status]}</h2>${o.status==='pending'?`<p class="tracker-pending">${Date.now()-o.createdAt>120000?'El local aún no ha confirmado tu pedido. Consulta al personal antes de pagar o enviar otro.':'El pedido se confirma cuando el equipo comienza su preparación. Si tarda, consulta al personal.'}</p>`:''}<p style="margin-top:8px">${o.table==='Retiro'?'Retiro en mostrador':'Mesa '+esc(o.table)}</p>${o.status==='ready'?'<div class="tracker-ready">¡Ya está! Acércate al área de entrega.</div>':''}${o.status==='cancelled'?'<div class="order-notes gap-top">Consulta al personal para conocer el motivo.</div>':`<div class="tracker-steps">${steps.map((s,i)=>`<div class="tracker-step ${index>=i?'done':''}"><i>${index>=i?'':i+1}</i>${orderLabels[s]}</div>`).join('')}</div>`}<div class="connection" style="justify-content:center"><span class="dot"></span>Esta página se actualiza automáticamente</div><button class="btn ${soundEnabled?'success':''} full-width gap-top" data-action="tracker-alert">${icon('bell')} ${soundEnabled?'Avisos activados en esta página':'Activar aviso cuando esté listo'}</button><p class="form-note">Mantén esta página abierta para recibir el aviso. Si cierras el navegador, esta página no puede notificarte.</p></section><section class="panel gap-top"><div class="panel-head"><h2>Lo que pediste</h2></div><div class="panel-body">${o.inventoryStatus==='partial'?'<div class="order-notes">Hay productos con receta o cantidades pendientes de configurar.</div>':''}<div class="order-items">${o.items.map(i=>`<div>${i.qty} × ${esc(i.name)}${i.removed?.length?`<small>Sin: ${esc(i.removed.join(', '))}</small>`:''}</div>`).join('')}</div><div class="order-line"><span>Total del pedido</span><strong>${money(o.total)}</strong></div></div></section><div class="actions gap-top"><a class="btn" href="/?view=menu${params.get('mesa')?'&mesa='+encodeURIComponent(params.get('mesa')):''}">Volver al menú</a><button class="btn" data-action="order-whatsapp" data-id="${o.id}">Compartir por WhatsApp</button></div><p class="form-note">Si no tienes teléfono, el personal puede entregarte tu número de turno y lo verás en la pantalla del local.</p></main>`;}

function renderBoard(){const kind=params.get('kind')||'orders',data=publicBoard(state,kind);let content='';if(kind==='gamer')content=`<div class="station-grid">${state.stations.map(s=>stationCard(s,true)).join('')}</div>`;if(kind==='park')content=`<div class="station-grid">${active('park').map(t=>`<article class="station ${remaining(t)<=0?'expired':''}" data-session="${t.id}"><div class="station-top"><span>Pase #${t.number}</span>${badge('Parque')}</div><div class="station-name">${t.minutes} minutos contratados</div><div class="station-time" data-countdown="${t.id}">${clock(remaining(t))}</div></article>`).join('')||empty('El parque está listo','Los pases activos aparecerán aquí.','tree')}</div>`;updateDisplay(state,kind,{orders:data.orders||[],dataReady:state.ordersReady===true,content,icon,money,clientBrand,makeQR,preview,soundEnabled,status:connection.status,error:connection.error,deviceName:connection.displayName||params.get('device'),onReady:()=>beep('ready')});tick();}
async function enableSound(){if(soundEnabled&&continuousAlarm.nodes){toast('Para detener la sirena, valida los tiempos vencidos.',true);return;}try{if(soundEnabled){soundEnabled=false;}else{audio??=new (window.AudioContext||window.webkitAudioContext)();await audio.resume();if(audio.state&&audio.state!=='running')throw new Error('audio suspended');soundEnabled=true;beep('test',true);}render();tick();toast(soundEnabled?'Sonido activado. Las alarmas se repetirán al vencer una sesión hasta reconocerlas.':'Sonido desactivado. Los avisos visuales siguen activos.');}catch{soundEnabled=false;toast('Activa el sonido con este botón y revisa el volumen del equipo. Los avisos visuales permanecen activos.',true);}}
function beep(mode='notification',force=false){if((!soundEnabled&&!force)||!audio)return;const settings=soundNotes(mode);if(!settings)return;const {notes,volume,wave}=settings;for(let i=0;i<notes.length;i++){const o=audio.createOscillator(),g=audio.createGain(),at=audio.currentTime+i*.24;o.connect(g);g.connect(audio.destination);o.type=wave;o.frequency.value=notes[i];g.gain.setValueAtTime(.0001,at);g.gain.exponentialRampToValueAtTime(Math.max(.0001,(mode==='end'?.18:.1)*volume),at+.02);g.gain.exponentialRampToValueAtTime(.0001,at+.2);o.start(at);o.stop(at+.22);}}
function tick(){const now=serverTime();$$('[data-countdown]').forEach(el=>{const t=state.tickets.find(t=>t.id===el.dataset.countdown);if(t)el.textContent=clock(remaining(t,now));});$$('[data-progress]').forEach(el=>{const t=state.tickets.find(t=>t.id===el.dataset.progress);if(t)el.style.width=Math.max(0,Math.min(100,remaining(t,now)/(t.minutes*60000)*100))+'%';});$$('[data-session]').forEach(el=>{const t=state.tickets.find(t=>t.id===el.dataset.session);if(!t)return;const ms=remaining(t,now);el.classList.toggle('near',ms>0&&ms<=300000);el.classList.toggle('expired',ms<=0);const label=el.querySelector('.station-top .badge');if(label&&t.area==='play'){label.textContent=ms<=0?'Tiempo terminado':ms<=300000?'Por terminar':'En uso';label.className='badge '+(ms<=0?'red':ms<=300000?'orange':'purple');}});const bc=$('#board-clock');if(bc)bc.textContent=new Date(now).toLocaleTimeString('es-VE',{timeZone:'America/Caracas',hour:'2-digit',minute:'2-digit'});const area=view==='board'?(params.get('kind')==='gamer'?'play':params.get('kind')==='park'?'park':null):role==='gamer'?'play':null,allowed=view==='staff'&&can('passes.view')||view==='board'&&['gamer','park'].includes(params.get('kind'));const result=sessionAlarms.poll(allowed?active(area):[],now,{audible:soundEnabled&&!!audio});continuousAlarm.sync(result.expired.length>0,audio,soundEnabled,Math.max(.75,soundNotes('test')?.volume??.75));if(result.sound&&result.sound!=='end')beep(result.sound);if(result.events.length){const messages=result.events.map(({ticket:t,level})=>`${t.area==='play'?state.stations.find(s=>s.id===t.stationId)?.name||'Play':'Parque · pase #'+t.number}: ${level==='end'?'tiempo terminado':level==='one'?'queda 1 minuto':'quedan menos de 5 minutos'}`);toast(messages.join(' · '));}renderTimeAlarm(result.expired);}
function renderTimeAlarm(expired){let root=$('#time-alarm-root');if(!root){root=document.createElement('div');root.id='time-alarm-root';root.className='time-expired-banner';root.setAttribute('role','alert');document.body.appendChild(root);}root.hidden=!expired.length;if(!expired.length)return;const signature=expired.map(t=>t.id+':'+t.endAt).join('|');if(root.dataset.signature===signature)return;root.dataset.signature=signature;root.innerHTML=`<div class="alarm-heading">${icon('bell')}<strong>${expired.length===1?'Tiempo terminado':expired.length+' tiempos terminados'}</strong></div>${expired.slice(0,2).map(t=>`<div class="time-expired-row"><span>${esc(t.area==='play'?state.stations.find(s=>s.id===t.stationId)?.name||'Play':'Parque')} · ${view==='staff'?esc(visitorName(t)):'Pase #'+t.number}</span><div><button class="btn small" data-action="acknowledge" data-id="${esc(t.id)}">Reconocer</button>${view==='staff'?`<button class="btn small primary" data-action="session-detail" data-id="${esc(t.id)}">Ver sesión</button>`:''}</div></div>`).join('')}<small>Confirma la salida para liberar el espacio.</small>${!soundEnabled?'<button class="btn primary small" data-action="sound">Activar sirena en este equipo</button>':''}${expired.length>2?'<button class="btn text" data-action="work-notifications">Ver todos los avisos →</button>':''}`;}
function editVisitor(id){const t=state.tickets.find(t=>t.id===id);if(!t)return;modal('Nombre del niño o jugador',`<form id="visitor-form"><div class="field"><label for="visitor-name">Nombre del niño o jugador</label><input id="visitor-name" name="childName" required maxlength="100" value="${esc(visitorName(t))}"></div><div class="field"><label for="visitor-responsible">Adulto responsable · opcional</label><input id="visitor-responsible" name="responsibleName" maxlength="100" value="${esc(t.responsibleName||'')}"></div><div class="modal-actions"><button type="button" class="btn" data-action="close-modal">Volver</button><button type="submit" class="btn primary">Guardar nombres</button></div></form>`);const f=$('#visitor-form');f.onsubmit=e=>{e.preventDefault();submit(f,async()=>{await execute('ticket.update',{id,childName:f.childName.value,responsibleName:f.responsibleName.value});closeModal();toast('Nombre actualizado en el pase y la sesión.');});};}
async function nextOrder(id){const o=state.orders.find(o=>o.id===id);const next={pending:'preparing',preparing:'ready',ready:'delivered'}[o?.status];if(!next)return;try{await execute('order.status',{id,status:next});toast(orderLabels[next]+'.');}catch(e){toast(e.message,true);}}
async function whatsappOrder(id){const o=state.orders.find(o=>o.id===id);if(!o)return;let phone=view==='staff'?o.phone||'':'';try{openWindow(whatsappLink(phone,orderMessage(o,location.origin)),'_blank','noopener');}catch{openWindow(whatsappLink('',orderMessage(o,location.origin)),'_blank','noopener');}}

document.addEventListener('click',async e=>{const b=e.target.closest('[data-action],[data-page],[data-time-tab],[data-order-tab],[data-menu-cat],[data-ticket-filter]');if(!b)return;if(b.tagName==='A'&&b.getAttribute('href')==='#')e.preventDefault();if(b.dataset.ticketFilter){ticketFilter=b.dataset.ticketFilter;render();return;}if(b.dataset.page){closeModal();page=b.dataset.page;search='';changeAddress('/admin?page='+encodeURIComponent(page));render();window.scrollTo(0,0);return;}if(b.dataset.timeTab){timeTab=b.dataset.timeTab;render();return;}if(b.dataset.orderTab){orderTab=b.dataset.orderTab;render();return;}if(b.dataset.menuCat){menuCat=b.dataset.menuCat;renderMenu();return;}const id=b.dataset.id;try{if(b.dataset.action?.startsWith('work-')){await workspaceAction(b.dataset.action,b,{...areaContext(),...actionContext()});return;}switch(b.dataset.action){case 'manual-recover':case 'manual-add':case 'manual-edit-line':case 'manual-plus':case 'manual-minus':case 'manual-category':manualAction(b.dataset.action,b,actionContext());break;case 'table-download':downloadTable(b.dataset.table,actionContext());break;case 'tables-print':printTables();break;case 'finance-tab':financeTab=b.dataset.tab;changeAddress('/admin?page=finances&tab='+encodeURIComponent(financeTab));render();break;case 'finance-new':financeForm(b.dataset.kind,actionContext());break;case 'finance-settle':await settleAccount(b.dataset.kind,id,actionContext());break;case 'finance-rate':await updateRate(actionContext());break;case 'show-order-ticket':{const o=state.orders.find(o=>o.id===id);if(o)showOrderTicket(o,actionContext());break;}case 'catalog-delete':deleteProduct(id,actionContext());break;case 'catalog-edit':await productForm(id,actionContext());break;case 'catalog-new':await productForm(null,actionContext());break;case 'new-beverage':await productForm(null,{...actionContext(),defaultCategory:'bebidas'},'unit');break;case 'catalog-new-unit':await productForm(null,actionContext(),'unit');break;case 'ingredient-new':ingredientForm(null,actionContext());break;case 'ingredient-edit':ingredientForm(id,actionContext());break;case 'inventory-purchase':inventoryMovementForm(id,'purchase',actionContext());break;case 'inventory-out':inventoryMovementForm(id,'out',actionContext());break;case 'menu-image-edit':menuImageForm(id,actionContext());break;case 'open-pass':{const t=state.tickets.find(x=>x.id===id);if(t?.token)openWindow('/pase.html?token='+encodeURIComponent(t.token),'_blank','noopener');else ticketDetail(id);break;}case 'open-nav':$('.sidebar')?.classList.add('open');$('.mobile-cover')?.classList.add('show');break;case 'close-nav':$('.sidebar')?.classList.remove('open');$('.mobile-cover')?.classList.remove('show');break;case 'close-modal':closeModal();break;case 'reload-app':location.reload();break;case 'scan-product':scanner(actionContext());break;case 'help':page='assistant';render();break;case 'sign-out':await signOut();break;case 'import-menu':await importOfficialMenu();break;case 'new-station':createStation();break;case 'recover-order':{const attempt=readPendingOrder();if(attempt){const r=await submitCustomerOrder(attempt.payload);localStorage.setItem(LAST_TOKEN_KEY,r.token);cart=[];saveClientCart();location.href=localLink('/seguimiento.html?token='+encodeURIComponent(r.token));}break;}case 'control-settings':controlSettings();break;case 'request-food':requestFood(id);break;case 'customer-cart':if(cart.length)openCart();else{toast('Elige un antojo para comenzar tu pedido.');scrollToSection('food-menu');}break;case 'scroll-food':e.preventDefault();scrollToSection('food-menu');break;case 'scroll-how':e.preventDefault();scrollToSection('how-to-order');break;case 'clear-food-search':foodSearch='';menuCat='Todos';renderMenu();break;case 'screen-wizard':screenWizard();break;case 'screen-guide':screenGuide();break;case 'prepared-screen':{const profile=screenProfiles().find(p=>p.id===id);if(profile)showPreparedScreen(profile);break;}case 'revoke-screen':await execute('device.revoke',{id});toast('Pantalla desvinculada.');break;case 'theme':{const dark=document.documentElement.dataset.theme!=='dark';document.documentElement.dataset.theme=dark?'dark':'light';localStorage.setItem(view==='menu'?'divermania.client.theme':'divermania.theme',dark?'dark':'light');break;}case 'sound':await enableSound();break;case 'new-ticket':newTicket();break;case 'ticket-detail':ticketDetail(id);break;case 'start-picker':startPicker(id);break;case 'start-session':startSession(id,b.dataset.station||'');break;case 'session-detail':sessionDetail(id);break;case 'extend':extendSession(id);break;case 'acknowledge':{const t=state.tickets.find(t=>t.id===id);if(t){sessionAlarms.acknowledge(t);tick();if(view==='staff'&&!preview&&navigator.onLine){try{await execute('session.acknowledge',{id:t.id,endAt:t.endAt});}catch{toast('Aviso silenciado aquí. No se pudo confirmar en los otros equipos.',true);break;}}}tick();toast('Alarma validada. Confirma la salida para liberar el espacio.');break;}case 'edit-visitor':editVisitor(id);break;case 'finish-session':modal('Finalizar sesión',`<p class="help-list">Confirma que la persona terminó de usar la estación o salió del parque. Esto liberará el espacio.</p><div class="modal-actions"><button class="btn" data-action="close-modal">Volver</button><button class="btn danger" data-action="finish-confirm" data-id="${id}">Confirmar salida</button></div>`);break;case 'finish-confirm':await execute('session.finish',{id});closeModal();toast('Sesión finalizada. Espacio disponible.');break;case 'new-customer':customerForm();break;case 'customer-detail':customerDetail(id);break;case 'confirm-payment':confirmPayment(id);break;case 'assign-customer':await execute('order.customer',{id,customerId:$('#assign-customer').value||null});closeModal();toast('Cliente asociado al pedido.');break;case 'order-detail':orderDetail(id);break;case 'order-next':await nextOrder(id);break;case 'cancel-order':modal('Cancelar pedido',`<p class="help-list">El pedido quedará cancelado en el control operativo. Si hubo un cobro, la devolución debe resolverse en el sistema de caja. Si el pedido aún no comenzó a prepararse, se devolverán los insumos reservados. Si ya está en preparación, no se devolverán automáticamente.</p><div class="modal-actions"><button class="btn" data-action="close-modal">Volver</button><button class="btn danger" data-action="cancel-confirm" data-id="${id}">Confirmar cancelación</button></div>`);break;case 'cancel-confirm':await execute('order.status',{id,status:'cancelled'});closeModal();toast('Pedido cancelado.');break;case 'print-order':printOrder(id);break;case 'new-order':newManualOrder();break;case 'legacy':page=({manual:'manual',mesas:'tables',catalogo:'catalog',inventario:'inventory',finanzas:'finances',pedidos:'orders'})[b.dataset.tab]||'overview';closeModal();changeAddress('/admin?page='+page);render();break;case 'show-qr':qrModal();break;case 'screen-qr':qrModal(b.dataset.kind);break;case 'copy-link':await copy(b.dataset.url);break;case 'open-menu':openWindow('/cliente','_blank','noopener');break;case 'open-board':openWindow('/?view=board&kind='+encodeURIComponent(b.dataset.kind),'_blank','noopener');break;case 'open-role':openWindow('/admin?role='+b.dataset.role+'&page='+({cash:'cash',entrance:'times',gamer:'times',kitchen:'orders'}[b.dataset.role]),'_blank','noopener');break;case 'custom-product':customProduct(id);break;case 'open-cart':openCart();break;case 'cart-minus':case 'cart-plus':{const x=cart[Number(b.dataset.index)];if(x)x.qty=Math.min(20,x.qty+(b.dataset.action==='cart-minus'?-1:1));cart=cart.filter(x=>x.qty>0);saveClientCart();if(!cart.length){closeModal();renderMenu();}else openCart();break;}case 'tracker-alert':{const permission='Notification' in window&&Notification.permission==='default'?Promise.resolve(Notification.requestPermission()).catch(()=>{}):null;if(!soundEnabled)await enableSound();if(permission)await permission;break;}case 'order-whatsapp':whatsappOrder(id);break;case 'print':if(view==='staff'&&!can('print'))throw new Error('Tu perfil no tiene permiso para imprimir.');document.documentElement.style.setProperty('--ticket-width',(localStorage.getItem('divermania.printer')||'80')+'mm');window.print();break;case 'fullscreen':if(!document.fullscreenElement)await document.documentElement.requestFullscreen();else await document.exitFullscreen();break;}}catch(err){formError(err);}});
function scrollToSection(id){document.getElementById(id)?.scrollIntoView({behavior:window.matchMedia?.('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'start'});}
document.addEventListener('input',e=>{if(e.target.dataset.manualField||e.target.id==='manual-search'){if(e.target.tagName!=='SELECT')manualInput(e,actionContext());return;}if(['catalog-search','inventory-search','images-search'].includes(e.target.id)){const id=e.target.id,pos=e.target.selectionStart;if(id==='inventory-search')inventorySearch=e.target.value;else if(id==='catalog-search')catalogSearch=e.target.value;else imageSearch=e.target.value;render();const el=$('#'+id);el.focus({preventScroll:true});el.setSelectionRange?.(pos,pos);}if(e.target.id==='food-search'){const pos=e.target.selectionStart;foodSearch=e.target.value;renderMenu();const input=$('#food-search');input.focus({preventScroll:true});input.setSelectionRange?.(pos,pos);}if(e.target.id==='customer-search'){const pos=e.target.selectionStart;search=e.target.value;render();const el=$('#customer-search');el.focus();el.setSelectionRange(pos,pos);}});
document.addEventListener('click',e=>{if(e.target.classList.contains('modal-backdrop'))closeModal();});
document.addEventListener('change',e=>{if(e.target.dataset.manualField&&e.target.tagName==='SELECT')manualInput(e,actionContext());});
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal();if(e.key==='Tab'&&$('#modal-root .modal')){const els=$$('#modal-root button,#modal-root input,#modal-root select,#modal-root textarea,#modal-root a').filter(el=>!el.disabled&&!el.hidden);const first=els[0],last=els[els.length-1];if(e.shiftKey&&document.activeElement===first){last?.focus();e.preventDefault();}else if(!e.shiftKey&&document.activeElement===last){first?.focus();e.preventDefault();}}});
var priorOrderIds=null,priorOrderStatus=null;subscribe(next=>{state=next;if(view==='staff'&&state.ordersReady){const ids=new Set(state.orders.map(o=>o.id));if(priorOrderIds&&state.orders.some(o=>!priorOrderIds.has(o.id)&&o.status==='pending'))beep('newOrder');if(priorOrderStatus&&state.orders.some(o=>o.status==='ready'&&priorOrderStatus.has(o.id)&&priorOrderStatus.get(o.id)!=='ready'))beep('ready');priorOrderIds=ids;priorOrderStatus=new Map(state.orders.map(o=>[o.id,o.status]));}const editingTheme=view==='staff'&&page==='appearance'&&$('#work-appearance-form')?.dataset.dirty==='true';if(!editingTheme&&view==='staff'&&state.workspace?.appearance)applyAppearance(state.workspace.appearance);if(!editingTheme)render();if(view==='menu'&&$('#checkout-form')){if(cart.length)openCart();else closeModal();}});
document.documentElement.dataset.theme=localStorage.getItem(view==='menu'?'divermania.client.theme':'divermania.theme')||'light';render();initialize().catch(err=>{connection.error=err.message;connection.status='error';render();});setInterval(tick,1000);setInterval(()=>{if(view==='track'&&state.orders.some(o=>o.status==='pending'))renderTracker();},30000);
let linkedTicketOpened=false;subscribe(()=>{const id=params.get('ticket');if(!linkedTicketOpened&&view==='staff'&&id&&state.tickets.some(t=>t.id===id)){linkedTicketOpened=true;ticketDetail(id);}});
document.addEventListener('visibilitychange',()=>{if(!document.hidden)tick();});
if('serviceWorker' in navigator)navigator.serviceWorker.register('/sw.js').catch(()=>{});

function loginScreen(){
 $('#app').innerHTML=`<main class="login"><img src="/logodivermania.png" alt="Divermanía" style="width:100px;height:82px;object-fit:contain"><h1>Acceso del equipo</h1><p>Entra con tu cuenta autorizada de Divermanía.</p>${connection.error?`<div class="banner-info">${esc(connection.error)}<button class="btn small" data-action="reload-app">Recargar acceso</button></div>`:''}<form id="login-form"><div class="field"><label for="login-email">Correo</label><input type="email" id="login-email" name="email" autocomplete="username" required></div><div class="field"><label for="login-password">Contraseña</label><input type="password" id="login-password" name="password" autocomplete="current-password" required></div><button class="btn primary full-width" type="submit">Entrar</button><button class="btn text full-width" id="login-reset" type="button">Olvidé mi contraseña</button><p id="login-error" role="alert" aria-live="polite" class="form-note"></p></form><a class="btn text gap-top" href="/admin?demo=1">Explorar administrador de prueba sin contraseña</a><p class="form-note">La prueba usa datos locales de este navegador. Para trabajar con los pedidos e inventario del negocio, entra con tu cuenta.</p><a class="btn text gap-top" href="/">Volver al menú del cliente →</a></main>`;
 const f=$('#login-form');f.onsubmit=async e=>{e.preventDefault();const b=f.querySelector('button');b.disabled=true;try{await signIn(f.email.value.trim(),f.password.value);}catch(error){$('#login-error').textContent=loginError(error);}finally{b.disabled=false;}};
 $('#login-reset').onclick=async()=>{const email=$('#login-email');if(!email.value.trim()||!email.checkValidity()){$('#login-error').textContent='Escribe tu correo para recibir el enlace de recuperación.';email.focus();return;}const button=$('#login-reset');button.disabled=true;try{await resetPassword(email.value);$('#login-error').textContent='Si el correo tiene una cuenta registrada, recibirás un enlace para restablecer la contraseña.';}catch(error){$('#login-error').textContent=error.code==='auth/user-not-found'?'Si el correo tiene una cuenta registrada, recibirás un enlace para restablecer la contraseña.':loginError(error);}finally{button.disabled=false;}};
}

function pairScreen(){
 $('#app').innerHTML=`<main class="board"><div class="pair-screen"><img src="/logodivermania.png" alt="Divermanía"><h1>Tu pantalla empieza aquí.</h1><p>En la computadora del administrador, abre “Pantallas y QR → Vincular pantalla”. Introduce aquí el código de 10 caracteres.</p>${connection.error?`<div class="banner-info">${esc(connection.error)}</div>`:''}<form id="pair-form"><div class="field"><label for="pair-code">Código de vinculación</label><input id="pair-code" name="code" placeholder="XXXXXXXXXX" maxlength="12" autocomplete="off" autocapitalize="characters" required></div><button class="btn primary full-width" type="submit">Vincular pantalla</button><p class="form-note" id="pair-error" role="alert"></p></form><p>El código vence a los 10 minutos y se utiliza una sola vez.</p></div></main>`;
 const f=$('#pair-form');f.onsubmit=async e=>{e.preventDefault();const b=f.querySelector('button');b.disabled=true;try{await pairDisplay(f.code.value);}catch(err){$('#pair-error').textContent=err.message;}finally{b.disabled=false;}};
}
async function importOfficialMenu(){
 const products=await fetch('/data/menu.json').then(r=>r.json());modal('Cargar el menú del PDF',`<div class="help-list"><p>Se cargarán ${products.length} productos y combos con los precios revisados del PDF. Los dos combos mixtos sin precio quedarán desactivados.</p><p>Los nombres que coincidan se actualizarán conservando sus recetas. Los productos que ya existen y no aparecen en el PDF no se eliminarán.</p><p>No se inventarán gramajes: las recetas nuevas quedan pendientes de configurar. Este paso actualiza tu catálogo cuando confirmes.</p></div><div class="modal-actions"><button class="btn" data-action="close-modal">Volver</button><button class="btn primary" id="confirm-import">Confirmar carga del menú</button></div>`);$('#confirm-import').onclick=async()=>{const b=$('#confirm-import');b.disabled=true;try{const result=await execute('catalog.import',{products});closeModal();toast(result.count+' productos procesados.');}catch(err){formError(err);b.disabled=false;}};
}
function createStation(){modal('Configurar una estación gamer',`<form id="station-form"><div class="field"><label for="station-name">Nombre de la estación</label><input id="station-name" name="stationName" placeholder="Ej. Play 1" required maxlength="50"></div><p class="form-note">Registra únicamente las estaciones que realmente existen en el local.</p><div class="modal-actions"><button class="btn" type="button" data-action="close-modal">Volver</button><button class="btn primary" type="submit">Guardar estación</button></div></form>`);const f=$('#station-form');f.onsubmit=e=>{e.preventDefault();submit(f,async()=>{await execute('station.save',{name:f.stationName.value});closeModal();toast('Estación guardada.');});};}
function voucherList(){const list=state.vouchers||[];return `<section class="panel gap-top"><div class="panel-head"><div><h2>Comida incluida en los pases</h2><p>Un canje por paquete. El tipo de perro se elige al solicitarlo a cocina.</p></div></div>${list.filter(v=>v.status==='pending').map(v=>`<div class="ticket-row"><span class="ticket-icon">${icon('bag')}</span><div><strong>Pase #${v.ticketNumber}</strong><p>${v.items.map(x=>x==='hotdog'?'Perro del paquete':'Cotufas').join(' + ')}</p></div><button class="btn small" data-action="request-food" data-id="${v.id}">Solicitar a cocina</button></div>`).join('')||empty('Sin canjes pendientes','Las compras de paquetes con comida aparecen aquí.','bag')}</section>`;}
function requestFood(id){const voucher=state.vouchers.find(v=>v.id===id);if(!voucher)return;const dogs=state.catalog.filter(p=>p.cat==='perros'&&p.enabled!==false&&(preview||p.id===state.settings?.hotdogProductId));modal('Comida del pase #'+voucher.ticketNumber,`<form id="food-form">${voucher.items.includes('hotdog')?`<div class="field"><label for="food-product">Perro incluido · definido por administración</label><select name="productId" id="food-product" required><option value="">Selecciona el producto que corresponde</option>${dogs.map(p=>`<option value="${p.id}">${esc(p.name)}</option>`).join('')}</select></div>`:''}<p class="form-note">${!preview&&!state.settings?.hotdogProductId?'El administrador debe definir qué perro incluye el paquete en “Parque y comida incluida”. ':''}El canje crea un pedido de cocina pagado por el paquete. Los insumos configurados se descuentan una sola vez. Las cotufas requieren su insumo o receta configurada.</p><div class="modal-actions"><button class="btn" type="button" data-action="close-modal">Volver</button><button class="btn primary" type="submit">Enviar a cocina</button></div></form>`);const f=$('#food-form');f.onsubmit=e=>{e.preventDefault();submit(f,async()=>{await execute('food.request',{id,productId:f.productId?.value||null});closeModal();toast('Canje enviado a cocina.');});};}

function newManualOrder(){page='manual';changeAddress('/admin?page=manual');render();window.scrollTo(0,0);}

function packageSection(){return `<section class="packages-section"><div class="food-section-head"><div><span class="menu-kicker">EL PLAN SIGUE DESPUÉS DE COMER</span><h2>PARQUE <em>Y GAMER</em></h2></div><span class="form-note">Compra y paga tu pase en taquilla.</span></div><div class="packages-grid">${Object.entries(packages).map(([area,plans])=>`<article><h3>${icon(area==='park'?'tree':'game')}${area==='park'?'Parque infantil':'Zona gamer'}</h3>${plans.map(p=>`<div><span>${packageLabel(p)}</span><strong>${money(p.price)}</strong></div>`).join('')}</article>`).join('')}</div><p class="form-note">Control adicional: $1,30 · Modalidad de cobro pendiente de confirmar.</p><div class="opening-hours"><h3>Nuestro horario</h3>${schedules.map(s=>`<span><strong>${s.days}</strong> ${s.open}–${s.close}</span>`).join('')}</div></section>`;}



function controlSettings(){const settings=state.settings||{},dogs=state.catalog.filter(p=>p.cat==='perros'&&p.enabled!==false),popcorn=state.catalog.filter(p=>/cotufa|palomita/i.test(p.name)&&p.enabled!==false);modal('Parque y comida de los paquetes',`<form id="settings-form"><div class="field"><label for="park-capacity">Capacidad del parque · opcional</label><input id="park-capacity" name="capacity" type="number" min="1" max="500" value="${state.capacity??''}"></div><div class="field"><label for="package-hotdog">Perro incluido en los paquetes</label><select id="package-hotdog" name="hotdogProductId"><option value="">Pendiente de confirmar</option>${dogs.map(p=>`<option value="${p.id}" ${settings.hotdogProductId===p.id?'selected':''}>${esc(p.name)}</option>`).join('')}</select></div><div class="field"><label for="package-popcorn">Cotufas incluidas en los paquetes</label><select id="package-popcorn" name="popcornProductId"><option value="">${settings.popcornRecipe?.length?'Conservar la receta manual guardada':'Pendiente de configurar'}</option>${popcorn.map(p=>`<option value="${p.id}" ${settings.popcornProductId===p.id?'selected':''}>${esc(p.name)} · ${p.inventoryMode==='unit'?'1 bolsa':'por receta'}</option>`).join('')}</select></div><p class="form-note">Registra las cotufas en Catálogo: si se preparan aquí, carga maíz, aceite y los demás ingredientes con cantidades por porción; si vienen empacadas, usa control por unidad. El canje descontará ese mismo producto.</p>${settings.popcornRecipe?.length?`<div class="banner-info">Receta anterior conservada: ${settings.popcornRecipe.map(i=>`${esc(state.inventory[i.id]?.name||i.id)}: ${i.qty} ${esc(state.inventory[i.id]?.unit||'')}`).join(' · ')}</div>`:''}<a class="btn text" href="/admin?page=catalog" target="_blank" rel="noopener">Abrir catálogo para configurar cotufas →</a><div class="modal-actions"><button class="btn" type="button" data-action="close-modal">Volver</button><button class="btn primary" type="submit">Guardar configuración</button></div></form>`);const f=$('#settings-form');f.onsubmit=e=>{e.preventDefault();submit(f,async()=>{await execute('config.save',{capacity:f.capacity.value?Number(f.capacity.value):null,hotdogProductId:f.hotdogProductId.value||null,popcornProductId:f.popcornProductId.value||null});closeModal();toast('Configuración guardada. Los canjes usarán los productos seleccionados.');});};}

function readPendingOrder(){try{return JSON.parse(localStorage.getItem(PENDING_ORDER_KEY)||'null');}catch{return null;}}
async function submitCustomerOrder(payload){if(!navigator.onLine)throw new Error('Sin conexión. Conservamos tu carrito; el pedido todavía no se ha enviado.');let attempt=readPendingOrder();if(attempt&&JSON.stringify(attempt.payload)!==JSON.stringify(payload))throw new Error('Hay un envío pendiente. Recupera su resultado desde el aviso del menú antes de cambiar el pedido.');attempt ||= {key:uid(),payload};localStorage.setItem(PENDING_ORDER_KEY,JSON.stringify(attempt));try{const result=await execute('order.create',payload,attempt.key);localStorage.removeItem(PENDING_ORDER_KEY);return result;}catch(error){if(preview||['functions/invalid-argument','functions/failed-precondition','functions/permission-denied','functions/not-found','functions/unauthenticated','functions/resource-exhausted'].includes(error.code))localStorage.removeItem(PENDING_ORDER_KEY);throw error;}}

window.addEventListener('storage',event=>{if(event.key===CLIENT_CART_KEY&&view==='menu'){cart=readClientCart();renderMenu();if($('#checkout-form')){if(cart.length)openCart();else closeModal();}}});
